365	/// The error for a slot whose parked output is gone. When the blanket wipe took it, name the
366	/// failure that triggered the wipe — that is the query's REAL error, and reporting only the
367	/// generic message is what made TPC-H q08 look like an exchange bug for weeks when it was an
368	/// OOM in HASH_JOIN.
369	fn missing_slot(poisoned: &HashMap<SenderSlot, String>, slot: &SenderSlot, verb: &str) -> String {
370	    match poisoned.get(slot) {
371	        Some(cause) => format!(
372	            "sender output for {slot:?} was discarded when another fragment on this CN failed: \
373	             {cause}"
374	        ),
375	        None => format!("no parked sender output to {verb} for {slot:?}"),
376	    }
377	}
