427	/// Runs one fragment on the engine thread, guaranteeing that the staging leases its remote
428	/// inputs sit in are released exactly once — immediately after each successful push, or in a
429	/// sweep when the run fails partway (a leaked lease would pin the arena for later queries).
430	fn run_fragment<'ctx>(
431	    context: &'ctx SiriusContext,
432	    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
433	    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
434	    poisoned: &HashMap<SenderSlot, String>,
435	    next_park_id: &mut u64,
436	    request: &ExecuteRequest,
437	) -> Result<Option<FragmentResult>, String> {
438	    // Every engine-thread line of this run (relay, remote push, cardinality, lease sweep) carries
439	    // the StarRocks ids; the span's close event is the engine-side elapsed time of the run.
440	    let span = tracing::info_span!(
441	        "fragment",
442	        query_id = tracing::field::Empty,
443	        fragment_instance_id = tracing::field::Empty
444	    );
445	    if let Some(id) = request.label.query_id {
446	        span.record("query_id", tracing::field::display(id));
447	    }
448	    if let Some(id) = request.label.fragment_instance_id {
449	        span.record("fragment_instance_id", tracing::field::display(id));
450	    }
451	    let _entered = span.enter();
452	    let mut released = std::collections::HashSet::new();
453	    let result = run_fragment_inner(
454	        context,
455	        parked,
456	        parked_slots,
457	        poisoned,
458	        next_park_id,
459	        request,
460	        &mut released,
461	    );
462	    if result.is_err() {
463	        for (_, _, batches) in &request.remote_inputs {
464	            for batch in batches {
465	                // `len == 0` batches never held a lease (metadata-only), and offsets in
466	                // `released` already went back in the push loop.
467	                if batch.len == 0 || released.contains(&batch.offset) {
468	                    continue;
469	                }
470	                if let Err(err) = context.staging_release(batch.offset) {
471	                    warn!(
472	                        offset = batch.offset,
473	                        error = %err,
474	                        "failed to release a remote-input staging lease after a fragment error"
475	                    );
476	                }
477	            }
478	        }
479	    }
480	    result
481	}
