483	/// Runs one fragment on the engine thread: declare its input streams, relay every parked sender
484	/// and push every staged remote batch into them, execute, then either park the output or return
485	/// the rows. Records each released remote-input lease offset in `released`.
486	fn run_fragment_inner<'ctx>(

486	fn run_fragment_inner<'ctx>(
487	    context: &'ctx SiriusContext,
488	    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
489	    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
490	    poisoned: &HashMap<SenderSlot, String>,
491	    next_park_id: &mut u64,
492	    request: &ExecuteRequest,
493	    released: &mut std::collections::HashSet<u64>,
494	) -> Result<Option<FragmentResult>, String> {
495	    let mut fragment = context
496	        .fragment()
497	        .map_err(|err| format!("failed to create fragment: {err}"))?;
498	
499	    // Name the engine's Quent Query after the StarRocks ids before build() opens it, so the
500	    // telemetry of this fragment and of its peers on other CNs share one query group.
501	    if let Some(query_label) = request.label.query_label() {
502	        let session_label = request.label.session_label().unwrap_or_default();
503	        fragment
504	            .set_query_label(&query_label, &session_label)
505	            .map_err(|err| format!("failed to label fragment {query_label}: {err}"))?;
506	    }
507	
508	    for schema in &request.stream_inputs {
509	        let stream_id = stream_id_of(schema.node_id)?;
510	        for column in &schema.columns {
511	            fragment
512	                .declare_input_column(stream_id, &column.name, &column.ty)
513	                .map_err(|err| {
514	                    format!(
515	                        "failed to declare column {} of stream {stream_id}: {err}",
516	                        column.name
517	                    )
518	                })?;
519	        }
520	        let senders = request
521	            .inputs
522	            .iter()
523	            .find(|(node_id, _)| *node_id == schema.node_id)
524	            .map(|(_, senders)| senders.as_slice())
525	            .unwrap_or_default();
526	        let remote_senders = request
527	            .remote_inputs
528	            .iter()
529	            .filter(|(node_id, _, _)| *node_id == schema.node_id)
530	            .map(|(_, sender_id, _)| *sender_id)
531	            .collect::<Vec<_>>();
532	        if senders.is_empty() && remote_senders.is_empty() {
533	            return Err(format!(
534	                "exchange node {} is read as a stream but no sender output — parked or remote — \
535	                 exists for it",
536	                schema.node_id
537	            ));
538	        }
539	        for sender_id in senders
540	            .iter()
541	            .map(|slot| slot.sender_id)
542	            .chain(remote_senders)
543	        {
544	            let sender_id =
545	                u32::try_from(sender_id).map_err(|_| format!("negative sender id {sender_id}"))?;
546	            fragment
547	                .declare_input_sender(stream_id, sender_id)
548	                .map_err(|err| format!("failed to declare sender on stream {stream_id}: {err}"))?;
549	        }
550	
551	        // The CN already holds every input of this fragment — parked local sender outputs and
552	        // staged remote batches — so it can declare the stream's EXACT row count and let
553	        // DuckDB's optimizer size join order / build-side selection (a stream source binds with
554	        // no rows behind it, so undeclared streams all estimate cardinality 1: the q07 2-CN
555	        // regression built its hash join on a multi-GB stream while a 2-row stream probed).
556	        // Best-effort by design: when any contributor's count is unknown (a spilled parked
557	        // batch, a remote frame that predates the wire's `rows` field), skip the declaration
558	        // and keep the legacy blind planning for this stream rather than failing the fragment.
559	        let local_rows: Option<u64> = senders
560	            .iter()
561	            .map(|slot| {
562	                let (park_id, sender_stream) = parked_slots.get(slot).copied()?;
563	                let entry = parked.get(&park_id)?;
564	                entry.fragment.output_row_count(sender_stream).ok()
565	            })
566	            .sum();
567	        let remote_rows: Option<u64> = request
568	            .remote_inputs
569	            .iter()
570	            .filter(|(node_id, _, _)| *node_id == schema.node_id)
571	            .flat_map(|(_, _, batches)| batches.iter().map(|batch| batch.rows))
572	            .sum();
573	        match (local_rows, remote_rows) {
574	            (Some(local), Some(remote)) => {
575	                let rows = local + remote;
576	                fragment
577	                    .declare_input_cardinality(stream_id, rows)
578	                    .map_err(|err| {
579	                        format!("failed to declare cardinality of stream {stream_id}: {err}")
580	                    })?;
581	                info!(stream_id, rows, "declared input stream cardinality");
582	            }
583	            _ => warn!(
584	                stream_id,
585	                "input stream row count unknown; planning without a declared cardinality"
586	            ),
587	        }
588	    }
589	
590	    // An intermediate fragment sinks into one output stream per destination (stream i belongs
591	    // to destination outputs[i]); a result fragment declares none and produces Arrow instead.
592	    for stream in 0..request.outputs.len() as u64 {
593	        fragment
594	            .declare_output(stream)
595	            .map_err(|err| format!("failed to declare fragment output stream {stream}: {err}"))?;
596	    }
597	    if request.broadcast && request.outputs.len() > 1 {
598	        fragment
599	            .declare_output_broadcast()
600	            .map_err(|err| format!("failed to declare the broadcast output mode: {err}"))?;
601	    } else if !request.hash_keys.is_empty() && request.outputs.len() > 1 {
602	        for &key in &request.hash_keys {
603	            let key = u32::try_from(key).map_err(|_| format!("hash key column {key} overflows"))?;
604	            fragment
605	                .declare_output_hash_key(key)
606	                .map_err(|err| format!("failed to declare hash key column {key}: {err}"))?;
607	        }
608	    }
609	
610	    fragment
611	        .build(&request.plan)
612	        .map_err(|err| format!("failed to plan fragment: {err}"))?;
613	
614	    // The fragment boundary itself: each sender's batches move into this fragment's input stream
615	    // as native handles. Nothing is converted, written, or copied.
616	    for schema in &request.stream_inputs {
617	        let stream_id = stream_id_of(schema.node_id)?;
618	        let senders = request
619	            .inputs
620	            .iter()
621	            .find(|(node_id, _)| *node_id == schema.node_id)
622	            .map(|(_, senders)| senders.as_slice())
623	            .unwrap_or_default();
624	        for slot in senders {
625	            let (park_id, sender_stream) = parked_slots
626	                .get(slot)
627	                .copied()
628	                .ok_or_else(|| format!("no parked sender output for {slot:?}"))?;
629	            let sender = parked
630	                .get_mut(&park_id)
631	                .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
632	            let sender_id = u32::try_from(slot.sender_id)
633	                .map_err(|_| format!("negative sender id {}", slot.sender_id))?;
634	            let moved = fragment
635	                .relay_from(&mut sender.fragment, sender_stream, stream_id, sender_id)
636	                .map_err(|err| format!("failed to relay sender {sender_id}: {err}"))?;
637	            // This destination's stream is drained; release its claim (the fragment drops with
638	            // the last claim, freeing the GPU batches).
639	            release_slot(parked, parked_slots, poisoned, slot)?;
640	            info!(
641	                stream_id,
642	                sender_id,
643	                batches = moved,
644	                "relayed native batches across a fragment boundary"
645	            );
646	        }
647	    }
648	
649	    // Remote senders: their packed batches already sit in this CN's staging arena. Push each
650	    // (deep copy into pool memory), release its lease immediately — copy-out-on-arrival makes
651	    // that safe — then close the sender.
652	    for (node_id, sender_id, batches) in &request.remote_inputs {
653	        let stream_id = stream_id_of(*node_id)?;
654	        let sender = u32::try_from(*sender_id)
655	            .map_err(|_| format!("negative remote sender id {sender_id}"))?;
656	        for batch in batches {
657	            let staged = sirius::PackedBatch {
658	                metadata: batch.metadata.clone(),
659	                offset: batch.offset,
660	                len: batch.len,
661	                // push_packed never reads the count; the receiver consumed it before build()
662	                // through declare_input_cardinality.
663	                rows: batch.rows.unwrap_or(0),
664	            };
665	            fragment.push_packed(stream_id, &staged).map_err(|err| {
666	                format!(
667	                    "failed to push a staged remote batch from sender {sender_id} into stream \
668	                     {stream_id}: {err}"
669	                )
670	            })?;
671	            if batch.len > 0 {
672	                context.staging_release(batch.offset).map_err(|err| {
673	                    format!(
674	                        "failed to release the staging lease at offset {} after pushing it: {err}",
675	                        batch.offset
676	                    )
677	                })?;
678	                released.insert(batch.offset);
679	            }
680	        }
681	        fragment.close_input(stream_id, sender).map_err(|err| {
682	            format!("failed to close remote sender {sender_id} on stream {stream_id}: {err}")
683	        })?;
684	        info!(
685	            stream_id,
686	            sender_id,
687	            batches = batches.len(),
688	            bytes = batches.iter().map(|batch| batch.len).sum::<u64>(),
689	            "received remote batches"
690	        );
691	    }
692	
693	    fragment
694	        .run()
695	        .map_err(|err| format!("failed to execute fragment: {err}"))?;
696	
697	    if !request.outputs.is_empty() {
698	        // Park ONCE; each destination claims (park id, its stream). A duplicate slot would let
699	        // two claims race over one stream -- refuse before inserting anything.
700	        let park_id = *next_park_id;
701	        *next_park_id += 1;
702	        for (stream, slot) in request.outputs.iter().enumerate() {
703	            if parked_slots.contains_key(slot) {
704	                return Err(format!(
705	                    "duplicate destination slot {slot:?} in one sender fan-out"
706	                ));
707	            }
708	            parked_slots.insert(slot.clone(), (park_id, stream as u64));
709	        }
710	        parked.insert(
711	            park_id,
712	            ParkedOutput {
713	                fragment,
714	                outstanding: request.outputs.len(),
715	            },
716	        );
717	        return Ok(None);
718	    }
719	    {
720	        // `into_arrow` drains the stream and drops the context-referencing wrapper here, on the
721	        // engine thread, returning owned batches whose buffers are released via their own Arrow C
722	        // release callbacks — independent of the context. So they are safe to send to, and drop
723	        // on, the caller's thread.
724	        fragment
725	            .into_arrow()
726	            .map(|result| Some(FragmentResult::new(result.batches)))
727	            .map_err(|err| err.to_string())
728	    }
729	}
