748	impl SiriusEngine {
749	    /// Sends one request to the engine thread and blocks for its answer.
750	    fn engine_call<T>(
751	        &self,
752	        make_request: impl FnOnce(Sender<Result<T, String>>) -> EngineRequest,
753	    ) -> Result<T, String> {
754	        let (respond_tx, respond_rx) = channel();
755	        self.requests
756	            .lock()
757	            .unwrap_or_else(|poisoned| poisoned.into_inner())
758	            .as_ref()
759	            .ok_or_else(|| "sirius-engine is shutting down".to_string())?
760	            .send(make_request(respond_tx))
761	            .map_err(|_| "sirius-engine thread is not running".to_string())?;
762	        respond_rx
763	            .recv()
764	            .map_err(|_| "sirius-engine thread dropped the response".to_string())?
765	    }
