832	impl Drop for SiriusEngine {
833	    fn drop(&mut self) {
834	        // Close the request channel so the engine thread's `recv()` returns and it drops the
835	        // context, then join for an ordered, complete teardown. The sender must drop before the
836	        // join or `recv()` would block forever.
837	        self.requests
838	            .lock()
839	            .unwrap_or_else(|poisoned| poisoned.into_inner())
840	            .take();
841	        if let Some(thread) = self
842	            .thread
843	            .lock()
844	            .unwrap_or_else(|poisoned| poisoned.into_inner())
845	            .take()
846	        {
847	            let _ = thread.join();
848	        }
849	    }
850	}
