 913	    /// Processes one fragment and buffers supported RESULT_SINK rows for later `fetch_data`.
 914	    /// Shared by single and batch dispatch; exchange receivers are registered until their local
 915	    /// sender output is materialized. Returns a receiver whose sender set this fragment
 916	    /// completed — the caller decides where it executes (RPC handlers hand it to the dispatch
 917	    /// worker; the worker itself runs it inline).
 918	    fn process_fragment(
 919	        &self,
 920	        params: &TExecPlanFragmentParams,
 921	    ) -> std::result::Result<FragmentOutcome, String> {
 922	        let params = self.resolve_descriptor_table(params)?;
 923	        let dump_seq = Self::dump_fragment(&params);
 924	        // Survey mode: accept every fragment so the FE dispatches (and we dump) the whole
 925	        // plan even when translation fails. Queries still fail at fetch_data.
 926	        if std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some() {
 927	            if let Err(err) = self.translate_fragment_logged(&params, dump_seq) {
 928	                tracing::warn!(error = %err, "translate-only mode: accepting untranslatable fragment");
 929	            }
 930	            return Ok(FragmentOutcome::default());
 931	        }
 932	        let expected_senders = Self::receiver_exchanges(&params)?;
 933	        if !expected_senders.is_empty() {
 934	            let fragment_instance_id = Self::fragment_instance_id(&params)
 935	                .ok_or_else(|| "exchange receiver is missing a fragment_instance_id".to_string())?;
 936	            if Self::is_mysql_result_sink(&params)? {
 937	                let query_id = Self::query_id(&params)
 938	                    .ok_or_else(|| "exchange receiver is missing a query_id".to_string())?;
 939	                self.results.reserve(fragment_instance_id, query_id);
 940	            }
 941	            return Ok(FragmentOutcome::from_ready(
 942	                self.exchanges
 943	                    .register_receiver(fragment_instance_id, expected_senders, params)?
 944	                    .into_iter()
 945	                    .collect(),
 946	            ));
 947	        }
 948	
 949	        let translated = self.translate_fragment_logged(&params, dump_seq)?;
 950	        self.execute_fragment(&params, translated)
 951	    }
