1020	    fn execute_fragment_with_inputs(
1021	        &self,
1022	        params: &TExecPlanFragmentParams,
1023	        translated: TranslatedPlan,
1024	        inputs: Vec<(i32, Vec<SenderSlot>)>,
1025	        remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)>,
1026	    ) -> std::result::Result<FragmentOutcome, String> {
1027	        if Self::is_mysql_result_sink(params)? {
1028	            let id = Self::fragment_instance_id(params).ok_or_else(|| {
1029	                "RESULT_SINK fragment is missing a fragment_instance_id".to_string()
1030	            })?;
1031	            let result = self
1032	                .run_labeled(
1033	                    "result",
1034	                    FragmentRun {
1035	                        plan: &translated,
1036	                        inputs: inputs.clone(),
1037	                        remote_inputs,
1038	                        outputs: Vec::new(),
1039	                        broadcast: false,
1040	                        hash_keys: Vec::new(),
1041	                        label: Self::fragment_label(params),
1042	                    },
1043	                )?
1044	                .ok_or_else(|| "result fragment returned no rows".to_string())?;
