1046	            self.results.insert(id, batch);
1047	            return Ok(FragmentOutcome::default());
1048	        }
1049	
1050	        let Some(sink) = params
1051	            .fragment
1052	            .as_ref()
1053	            .and_then(|fragment| fragment.output_sink.as_ref())
1054	        else {
1055	            // The FE attaches a sink to every fragment it dispatches (PlanFragment.toThrift),
1056	            // so a sinkless fragment only reaches here from a translate-only fixture.
1057	            tracing::warn!(
1058	                fragment = %Self::fragment_context(params),
1059	                "fragment carries no output sink; nothing consumes its output"
1060	            );
1061	            return Ok(FragmentOutcome::default());
1062	        };
1063	        // Accepting an unhandled sink discards the fragment's whole output: its consumers wait
1064	        // forever, the FE's fetch_data long-poll times out, and its serial channel wedges
1065	        // cluster-wide. Refuse by name so the FE error says which plan shape is unsupported.
1066	        if sink.type_ != TDataSinkType::DATA_STREAM_SINK {
1067	            return Err(format!(
1068	                "{} carries a {} output sink, which this CN does not support",
1069	                Self::fragment_context(params),
1070	                Self::data_sink_type_name(sink.type_)
1071	            ));
1072	        }
1073	        let stream_sink = sink.stream_sink.as_ref().ok_or_else(|| {
1074	            format!(
1075	                "{} carries a DATA_STREAM_SINK with no stream_sink payload",
1076	                Self::fragment_context(params)
1077	            )
1078	        })?;
1079	        if stream_sink.limit.is_some_and(|limit| limit >= 0) {
1080	            return Err("data stream sink limits are not supported".to_string());
1081	        }
1082	        if let Some(columns) = stream_sink
1083	            .output_columns
1084	            .as_ref()
1085	            .filter(|columns| !columns.is_empty())
1086	            && columns
1087	                .iter()
1088	                .copied()
1089	                .ne(0..translated.output_names.len() as i32)
1090	        {
1091	            return Err(
1092	                "non-identity data stream sink output_columns are not supported".to_string(),
1093	            );
1094	        }
1095	        let exec = params
1096	            .params
1097	            .as_ref()
1098	            .ok_or_else(|| "DATA_STREAM_SINK fragment is missing execution params".to_string())?;
1099	        let destinations = exec
1100	            .destinations
1101	            .as_ref()
1102	            .filter(|destinations| !destinations.is_empty())
1103	            .ok_or_else(|| "DATA_STREAM_SINK fragment has no destinations".to_string())?;
1104	        let sender_id = exec.sender_id.unwrap_or(0);
1105	        // Fan-out shape: one destination is a gather regardless of the partition label;
1106	        // UNPARTITIONED with N destinations broadcasts the full output to every receiver
1107	        // (each destination drains its own copy from its own output stream). Hash-partitioned
1108	        // fan-out is the second half of #838 and still refuses.
1109	        if destinations.len() > 1 {
1110	            use starrocks_thrift::partitions::TPartitionType;
1111	            match stream_sink.output_partition.type_ {
1112	                TPartitionType::UNPARTITIONED => {}
1113	                TPartitionType::HASH_PARTITIONED => {
1114	                    if translated.output_partition_columns.is_none() {
1115	                        return Err(
1116	                            "a hash-partitioned data stream sink translated without partition \
1117	                             key columns"
1118	                                .to_string(),
1119	                        );
1120	                    }
1121	                }
1122	                other => {
1123	                    return Err(format!(
1124	                        "a data stream sink with {} destinations carries partition type {:?}, \
1125	                         which this CN does not support",
1126	                        destinations.len(),
1127	                        other
1128	                    ));
1129	                }
1130	            }
1131	        }
1132	        let hash_keys = if destinations.len() > 1 {
1133	            translated
1134	                .output_partition_columns
1135	                .clone()
1136	                .unwrap_or_default()
1137	        } else {
1138	            Vec::new()
1139	        };
1140	        let broadcast = destinations.len() > 1 && hash_keys.is_empty();
1141	
1142	        // Route every destination BEFORE running: a remote destination without a transport (or
1143	        // a duplicate) must fail before any GPU work happens. Destination i then drains the
1144	        // sender's output stream i -- the FE's destination order, positionally.
1145	        let mut slots: Vec<SenderSlot> = Vec::with_capacity(destinations.len());
1146	        let mut routes = Vec::with_capacity(destinations.len());
1147	        for destination in destinations {
1148	            let slot = SenderSlot {
1149	                fragment_instance_id: FragmentInstanceId::from(&destination.fragment_instance_id),
1150	                node_id: stream_sink.dest_node_id,
1151	                sender_id,
1152	            };
1153	            if slots.contains(&slot) {
1154	                return Err(format!(
1155	                    "duplicate destination {slot:?} in one data stream sink; two claims would \
1156	                     race over one output stream"
1157	                ));
1158	            }
1159	            let route = self.route_destination(destination)?;
1160	            if let DestinationRoute::Remote { host, brpc_port } = &route
1161	                && self.transport.is_none()
1162	            {
1163	                return Err(format!(
1164	                    "cross-node exchange to {host}:{brpc_port} needs the nixl transport \
1165	                     tier, which is not active: build the CN with the `nixl-transport` \
1166	                     feature (default) and set SIRIUS_EXCHANGE_STAGING_BYTES so the \
1167	                     exchange staging arena exists"
1168	                ));
1169	            }
1170	            slots.push(slot);
1171	            routes.push(route);
1172	        }
1173	
1174	        // The sender's rows stay on the GPU, parked once with one output stream per
1175	        // destination; only rendezvous bookkeeping and packed exports leave the engine thread.
1176	        self.run_labeled(
1177	            "sender",
1178	            FragmentRun {
1179	                plan: &translated,
1180	                inputs,
1181	                remote_inputs,
1182	                outputs: slots.clone(),
1183	                broadcast,
1184	                hash_keys,
1185	                label: Self::fragment_label(params),
1186	            },
1187	        )?;
1188	
1189	        // Local destinations first: their rendezvous is immediate bookkeeping and fails fast.
1190	        let mut ready_receivers = Vec::new();
1191	        for (slot, route) in slots.iter().zip(&routes) {
1192	            if matches!(route, DestinationRoute::Local) {
1193	                let ready = self.exchanges.push_sender(
1194	                    ExchangeKey {
1195	                        fragment_instance_id: slot.fragment_instance_id,
1196	                        node_id: slot.node_id,
1197	                    },
1198	                    sender_id,
1199	                    SenderSource::LocalParked {
1200	                        names: translated.output_names.clone(),
1201	                        slot: *slot,
1202	                    },
1203	                )?;
1204	                ready_receivers.extend(ready);
1205	            }
1206	        }
1207	        // Remote destinations second: POST each drain and keep its ticket instead of blocking
1208	        // here. The caller dispatches `ready_receivers` first and joins the tickets after, so a
1209	        // local receiver whose sender set this push just completed starts while the transport
1210	        // thread is still draining this CN's remote destinations — measured, that wait was
1211	        // 3 x 30 ms per CN on q14 SF500's 948 MB/destination stage.
1212	        //
1213	        // ORDER IS UNCHANGED, and deliberately so: one FIFO request channel into ONE transport
1214	        // thread that still handles `SendFragment` inline means the drains still run one at a
1215	        // time, in the FE's destination order, with every frame of a destination issued by that
1216	        // single thread. `seq`, eos, and the exactly-once `drop_parked` all stay inside the
1217	        // transport thread's own drain loop, so the receiver's per-(exchange, sender) gap check
1218	        // (local_exchange.rs:180-197) sees exactly the byte sequence it sees today.
1219	        let mut drains = SenderDrains::default();
1220	        for (slot, route) in slots.iter().zip(&routes) {
1221	            if let DestinationRoute::Remote { host, brpc_port } = route {
1222	                let transport = self.transport.as_ref().expect("routed before running");
1223	                let spec = RemoteSendSpec {
1224	                    host: host.clone(),
1225	                    brpc_port: *brpc_port,
1226	                    slot: *slot,
1227	                    names: translated.output_names.clone(),
1228	                    label: Self::fragment_label(params),
1229	                };
1230	                match transport.start_fragment(spec) {
1231	                    Ok(ticket) => drains.push(ticket),
1232	                    // Posting failed (the transport is shutting down). Join what is already in
1233	                    // flight before unwinding: a ticket dropped un-joined discards a real drain
1234	                    // failure, and this is the one path where tickets exist and `?` could fire.
1235	                    Err(err) => {
1236	                        let _ = drains.join();
1237	                        return Err(err);
1238	                    }
1239	                }
1240	            }
1241	        }
1242	        Ok(FragmentOutcome {
1243	            ready: ready_receivers,
1244	            drains,
1245	        })
1246	    }
