  1	//! In-memory buffer of executed-fragment results awaiting FE `fetch_data` collection.
  2	//!
  3	//! StarRocks dispatches a fragment with `exec_plan_fragment`, then polls `fetch_data` with the
  4	//! fragment instance id until end-of-stream. This store bridges those two RPCs: the exec handler
  5	//! buffers a fragment's rows here, and each `fetch_data` poll drains them.
  6	
  7	use std::fmt;
  8	use std::{collections::HashMap, sync::Mutex};
  9	
 10	use starrocks_thrift::data::TResultBatch;
 11	use starrocks_thrift::types::TUniqueId;
 12	use uuid::Uuid;
 13	
 14	use crate::proto::starrocks::PUniqueId;
