 31	    /// The `hi`/`lo` halves back out, for proto messages that carry them (`PUniqueId`).
 32	    #[cfg_attr(not(feature = "nixl-transport"), allow(dead_code))]
 33	    pub(crate) fn as_halves(&self) -> (i64, i64) {
 34	        let (hi, lo) = self.0.as_u64_pair();
 35	        (hi as i64, lo as i64)
 36	    }
 37	}
 38	
 39	impl From<&TUniqueId> for FragmentInstanceId {
 40	    fn from(id: &TUniqueId) -> Self {
 41	        Self::from_halves(id.hi, id.lo)
 42	    }
 43	}
 44	
 45	impl From<&PUniqueId> for FragmentInstanceId {
 46	    fn from(id: &PUniqueId) -> Self {
 47	        Self::from_halves(id.hi, id.lo)
 48	    }
