 57	/// One buffered fragment result and where the FE `fetch_data` poll is in draining it.
 58	#[derive(Debug)]
 59	enum FragmentState {
 60	    /// Result fragment accepted but waiting for its exchange input.
 61	    Waiting,
 62	    /// Rows produced, not yet delivered.
 63	    Pending(TResultBatch),
 64	    /// Rows delivered; the next poll reports end-of-stream.
 65	    Drained,
 66	    /// Execution failed (e.g. on the dispatch worker); every poll re-reports the cause so the
 67	    /// FE errors instead of polling a `Waiting` entry forever.
 68	    Failed(String),
 69	}
 70	
 71	/// What a single `fetch_data` poll should return to the FE.
 72	#[derive(Debug)]
 73	pub(crate) enum FetchOutcome {
 74	    /// Result-stream progress for a live fragment.
 75	    Rows {
 76	        /// Result rows to ship as the response attachment, when present.
 77	        batch: Option<TResultBatch>,
 78	        /// Monotonic packet sequence the FE uses to detect lost packets.
 79	        packet_seq: i64,
 80	        /// End-of-stream marker; the FE stops polling once true.
 81	        eos: bool,
 82	    },
 83	    /// The fragment failed; the poll must surface this cause as an error.
 84	    Failed(String),
 85	}
 86	
 87	/// Everything behind the store's one mutex: buffered fragment states plus the per-query
 88	/// bookkeeping that lets any fragment failure reach the result instances the FE polls.
 89	#[derive(Debug, Default)]
 90	struct StoreState {
 91	    /// Buffered results keyed by fragment instance id.
 92	    fragments: HashMap<FragmentInstanceId, FragmentState>,
 93	    /// Result-fragment instances reserved per query, so a failure anywhere in the query can
 94	    /// fail every id the FE is polling on this CN.
 95	    query_results: HashMap<FragmentInstanceId, Vec<FragmentInstanceId>>,
 96	    /// First failure recorded per query. A result fragment that reserves *after* the failure
 97	    /// landed fails immediately instead of waiting on senders that will never deliver.
 98	    query_failures: HashMap<FragmentInstanceId, String>,
 99	}
100	
101	/// Process-wide store of fragment results keyed by fragment instance id.
102	///
103	/// Shared across all BRPC connections via an `Arc` inside the compute-node service, so a
104	/// `fetch_data` poll on one connection sees results buffered by an `exec_plan_fragment` on another.
105	#[derive(Debug, Default)]
106	pub(crate) struct ResultStore {
107	    /// Fragment states plus per-query failure bookkeeping (see [`StoreState`]).
108	    inner: Mutex<StoreState>,
109	    /// Signalled whenever a fragment leaves `Waiting` (rows buffered or failure recorded), so a
110	    /// long-polling `fetch_data` can block instead of replying not-ready. An empty reply is not
111	    /// harmless: the FE's ResultReceiver counts every packet, so a not-ready reply consumes a
112	    /// sequence number and the rows that follow arrive with a stale one ("expect=1, receive=0").
113	    ready: std::sync::Condvar,
114	}
115	
116	impl ResultStore {
117	    /// Marks an accepted result fragment whose execution is waiting on an exchange sender,
118	    /// remembering which query it belongs to. If that query already failed (an intermediate
119	    /// fragment can fail before the FE dispatches the result fragment), the reservation lands
120	    /// as the failure so the very first `fetch_data` poll reports it.
121	    pub(crate) fn reserve(&self, id: FragmentInstanceId, query_id: FragmentInstanceId) {
122	        let mut state = self.lock();
123	        let results = state.query_results.entry(query_id).or_default();
124	        if !results.contains(&id) {
125	            results.push(id);
126	        }
127	        if let Some(cause) = state.query_failures.get(&query_id).cloned() {
128	            state.fragments.insert(id, FragmentState::Failed(cause));
129	            drop(state);
130	            self.ready.notify_all();
131	            return;
132	        }
133	        state.fragments.entry(id).or_insert(FragmentState::Waiting);
134	    }
135	
136	    /// Buffers an executed fragment's result for later `fetch_data` collection. A recorded
137	    /// failure sticks: rows landing after the query failed elsewhere must not turn a loud
138	    /// error back into a silently incomplete result.
139	    pub(crate) fn insert(&self, id: FragmentInstanceId, batch: TResultBatch) {
140	        let mut state = self.lock();
141	        if !matches!(state.fragments.get(&id), Some(FragmentState::Failed(_))) {
142	            state.fragments.insert(id, FragmentState::Pending(batch));
143	        }
144	        drop(state);
145	        self.ready.notify_all();
146	    }
147	
148	    /// Marks a fragment failed so `fetch_data` reports the cause instead of waiting forever.
149	    /// The failure sticks: like `Drained`, repeat polls keep re-reporting it rather than
150	    /// reverting to "unknown fragment".
151	    pub(crate) fn fail(&self, id: FragmentInstanceId, error: String) {
152	        self.lock()
153	            .fragments
154	            .insert(id, FragmentState::Failed(error));
155	        self.ready.notify_all();
156	    }
157	
158	    /// Fails fragment `failed_id` and every result-fragment instance reserved for `query_id`,
159	    /// waking any `fetch_data` long-poll. Also records the failure at query level so a result
160	    /// fragment that reserves later fails on arrival — without this, an intermediate fragment
161	    /// failing before the result fragment registers would be lost and the FE would poll until
162	    /// its timeout. The propagated message carries the original fragment's error verbatim.
163	    pub(crate) fn fail_query(
164	        &self,
165	        query_id: FragmentInstanceId,
166	        failed_id: FragmentInstanceId,
167	        error: String,
168	    ) {
169	        let mut state = self.lock();
170	        let cause = format!("fragment instance {failed_id} failed: {error}");
171	        state
172	            .fragments
173	            .insert(failed_id, FragmentState::Failed(error));
174	        // First failure wins: later failures are usually downstream echoes of the first.
175	        let cause = state
176	            .query_failures
177	            .entry(query_id)
178	            .or_insert(cause)
179	            .clone();
180	        let results = state
181	            .query_results
182	            .get(&query_id)
183	            .cloned()
184	            .unwrap_or_default();
185	        for result_id in results {
186	            if result_id == failed_id
187	                || matches!(
188	                    state.fragments.get(&result_id),
189	                    Some(FragmentState::Failed(_))
190	                )
191	            {
192	                continue;
193	            }
194	            state
195	                .fragments
196	                .insert(result_id, FragmentState::Failed(cause.clone()));
197	        }
198	        drop(state);
199	        self.ready.notify_all();
200	    }
201	
202	    /// Best-effort cancellation mark: a still-`Waiting` entry becomes a failure so a
203	    /// `fetch_data` long-poll returns instead of blocking out its timeout. Delivered,
204	    /// drained, or already-failed entries keep their state; unknown ids are ignored.
205	    pub(crate) fn cancel(&self, id: FragmentInstanceId, reason: String) {
206	        let mut state = self.lock();
207	        if let Some(entry @ FragmentState::Waiting) = state.fragments.get_mut(&id) {
208	            *entry = FragmentState::Failed(reason);
209	            drop(state);
210	            self.ready.notify_all();
211	        }
212	    }
213	
214	    /// Blocks until fragment `id` has something to report, then advances the state machine —
215	    /// the long-poll `fetch_data` needs now that receivers execute on the dispatch thread. The
216	    /// stock BE holds the rpc open until the sink produces; replying not-ready instead desyncs
217	    /// the FE's packet counter (see `ready`). A timeout is a *loud* failure rather than an empty
218	    /// reply, for the same reason.
219	    pub(crate) fn wait_ready(
220	        &self,
221	        id: FragmentInstanceId,
222	        timeout: std::time::Duration,
223	    ) -> Option<FetchOutcome> {
224	        let deadline = std::time::Instant::now() + timeout;
225	        let mut guard = self.lock();
226	        while let Some(FragmentState::Waiting) = guard.fragments.get(&id) {
227	            let now = std::time::Instant::now();
228	            if now >= deadline {
229	                return Some(FetchOutcome::Failed(format!(
230	                    "timed out after {timeout:?} waiting for fragment instance {id} to produce \
231	                     rows (its exchange senders may have stalled)"
232	                )));
233	            }
234	            let (g, wait) = self
235	                .ready
236	                .wait_timeout(guard, deadline - now)
237	                .unwrap_or_else(|poisoned| poisoned.into_inner());
238	            guard = g;
239	            let _ = wait;
240	        }
241	        drop(guard);
242	        self.take_next(id)
243	    }
244	
245	    /// Advances the `fetch_data` state machine for one fragment: deliver rows once, then EOS.
246	    /// Returns `None` for an id this CN never buffered, which the caller reports as an error
247	    /// (StarRocks treats a missing result buffer as a failure, not an empty result). A drained
248	    /// fragment stays in the map so a repeat poll still reports EOS rather than reading as unknown.
249	    ///
250	    /// TODO(starrocks-execute): this is a single-batch, single-poller model. The real executor
251	    /// needs (a) chunked/streamed delivery of many batches, (b) safety against duplicate or
252	    /// concurrent polls (advance state only after the response is written; keep a per-fragment
253	    /// in-flight guard), and (c) eviction of drained entries (and the per-query bookkeeping) on
254	    /// `cancel_plan_fragment`/timeout so the maps do not grow for the process lifetime.
255	    pub(crate) fn take_next(&self, id: FragmentInstanceId) -> Option<FetchOutcome> {
256	        let mut guard = self.lock();
257	        match guard.fragments.get_mut(&id) {
258	            None => None,
259	            Some(FragmentState::Waiting) => Some(FetchOutcome::Rows {
260	                batch: None,
261	                packet_seq: 0,
262	                eos: false,
263	            }),
264	            Some(state @ FragmentState::Pending(_)) => {
265	                let FragmentState::Pending(batch) =
266	                    std::mem::replace(state, FragmentState::Drained)
267	                else {
268	                    unreachable!("state matched Pending")
269	                };
270	                Some(FetchOutcome::Rows {
271	                    batch: Some(batch),
272	                    packet_seq: 0,
273	                    eos: false,
274	                })
275	            }
276	            Some(FragmentState::Drained) => Some(FetchOutcome::Rows {
277	                batch: None,
278	                packet_seq: 1,
279	                eos: true,
280	            }),
281	            Some(FragmentState::Failed(error)) => Some(FetchOutcome::Failed(error.clone())),
282	        }
283	    }
284	
285	    /// Locks the inner state, recovering from a poisoned mutex (state is disposable result data).
286	    fn lock(&self) -> std::sync::MutexGuard<'_, StoreState> {
287	        self.inner
288	            .lock()
289	            .unwrap_or_else(|poisoned| poisoned.into_inner())
290	    }
291	}
