 15	/// Output of executing one plan fragment: Arrow batches matching the fragment output schema.
 16	///
 17	/// Only a *result* fragment produces one. An intermediate fragment's output never becomes Arrow —
 18	/// it stays on the GPU as native batches for the fragment that consumes it.
 19	#[derive(Clone, Debug)]
 20	pub struct FragmentResult {
 21	    /// Result batches in fragment output order. Empty for a fragment with no output columns.
 22	    pub(crate) batches: Vec<RecordBatch>,
 23	}
