 51	/// Telemetry identity of one fragment run, shared by everything that reports on it.
 52	///
 53	/// The engine reports the fragment as the Quent Query `<query id>:<fragment instance id>` inside
 54	/// the QueryGroup `<query id>` (see `sirius::Fragment::set_query_label`), and the CN's own
 55	/// start/finish and transmit log lines carry the same two ids next to the CN's exchange endpoint,
 56	/// so the halves of one StarRocks query running on different CNs line up under one label.
 57	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
 58	pub struct FragmentLabel {
 59	    /// StarRocks query id, shared by every fragment instance of the query.
 60	    pub query_id: Option<FragmentInstanceId>,
 61	    /// The fragment instance the FE dispatched.
 62	    pub fragment_instance_id: Option<FragmentInstanceId>,
 63	}
