 65	impl FragmentLabel {
 66	    /// Quent Query `instance_name`: `<query id>:<fragment instance id>`. `None` when the dispatch
 67	    /// carried no ids (translate-only fixtures), leaving the engine's anonymous default.
 68	    pub fn query_label(&self) -> Option<String> {
 69	        Some(format!("{}:{}", self.query_id?, self.fragment_instance_id?))
 70	    }
