 78	    pub fn log_ids(&self) -> (String, String) {
 79	        let text = |id: Option<FragmentInstanceId>| {
 80	            id.map_or_else(|| "-".to_string(), |id| id.to_string())
 81	        };
 82	        (text(self.query_id), text(self.fragment_instance_id))
 83	    }
