 86	/// One packed batch sitting in an exchange staging arena as cudf packed bytes.
 87	///
 88	/// The neutral wire shape of the nixl tier: on the sender it names a lease in the *local* arena
 89	/// (filled by `export_packed`), on the receiver a lease in the *receiver's* arena (filled by a
 90	/// nixl WRITE). Whoever holds the arena releases the lease after the bytes leave it.
 91	#[derive(Clone, Debug, PartialEq, Eq)]
 92	pub struct StagedBatch {
 93	    /// Host-side cudf pack metadata (travels over brpc next to the device payload).
 94	    pub metadata: Vec<u8>,
 95	    /// Byte offset of the packed payload from the arena base. `0` with `len == 0` means no
 96	    /// lease exists for this batch (a metadata-only empty batch) — nothing to release.
 97	    pub offset: u64,
 98	    /// Length of the packed payload in bytes.
 99	    pub len: u64,
100	    /// Exact row count of the packed table (from `export_packed`, carried on the transmit
101	    /// frame). The receiver sums the counts per stream into `declare_input_cardinality` so the
102	    /// optimizer can size the stream. `None` when the frame predates the wire field: the
103	    /// receiver then declares nothing for the stream and keeps the legacy blind planning.
104	    pub rows: Option<u64>,
105	}
