145	pub struct FragmentRun<'a> {
146	    /// Translated plan, including the schema of every exchange lowered to a stream read.
147	    pub plan: &'a TranslatedPlan,
148	    /// Parked sender outputs to relay into this fragment, keyed by receiver exchange node id.
149	    pub inputs: Vec<(i32, Vec<SenderSlot>)>,
150	    /// Remote sender outputs already staged in this CN's arena, as
151	    /// `(exchange node id, sender id, batches)`: pushed via `push_packed` + `close_input`
152	    /// before the fragment runs, with each lease released the moment its push returns.
153	    pub remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)>,
154	    /// Non-empty for a sender fragment: the fragment parks ONCE and output stream i belongs to
155	    /// destination `outputs[i]` (the FE's destination order). Each destination drains its own
156	    /// stream; the parked fragment drops when the last destination releases it.
157	    pub outputs: Vec<SenderSlot>,
158	    /// Every destination receives the full output (a broadcast sink). With `outputs.len() > 1`
159	    /// and `broadcast == false`, `hash_keys` routes rows instead.
160	    pub broadcast: bool,
161	    /// Hash-partition key columns (output column indices, in the exchange's shared
162	    /// partition-expression order). Non-empty exactly for a hash-partitioned fan-out.
163	    pub hash_keys: Vec<usize>,
164	    /// Telemetry identity the engine labels this run's query with.
165	    pub label: FragmentLabel,
166	}
